import { useMemo, useState } from 'react';
import { JxTable, JxBadge, JxPagination, JxEmptyState } from '@jinx-ui/react';

export interface User {
  id: string;
  name: string;
  role: string;
  active: boolean;
}

interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);

  const visible = useMemo(
    () => users.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [users, currentPage],
  );

  if (users.length === 0) {
    return <JxEmptyState title="Пользователей нет" message="Список пуст." />;
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
      <JxTable>
        <thead>
          <tr>
            <th>Имя</th>
            <th>Роль</th>
            <th>Статус</th>
          </tr>
        </thead>
        <tbody>
          {visible.map((user) => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.role}</td>
              <td>
                <JxBadge tone={user.active ? 'success' : 'default'} dot>
                  {user.active ? 'Активен' : 'Отключён'}
                </JxBadge>
              </td>
            </tr>
          ))}
        </tbody>
      </JxTable>
      {pageCount > 1 && (
        <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
      )}
    </div>
  );
}

